constraints:
1 <= n <= 10^{5}

expected time complexity: O(nlog(n))
expected auxiliary space: O(n)

standard_solution_code:
class Solution:

	def CommonFactor(self, n):
		sieve = [True] * (n + 1)
		res = [False] * (n + 1)
		for i in range(2, n + 1):
			if sieve[i]:
				can = n % i == 0
				for j in range(i, n + 1, i):
					sieve[j] = False
					res[j] |= can
		return sum(res)
